// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {
	// GetDataset Discover the current Dataset
	// (GET /dataset)
	GetDataset(ctx context.Context, request GetDatasetRequestObject) (GetDatasetResponseObject, error)
	// CreateEntity Enroll an Asset with deployment authorization
	// (POST /entities)
	CreateEntity(ctx context.Context, request CreateEntityRequestObject) (CreateEntityResponseObject, error)
	// GetEntity Read an operational Entity
	// (GET /entities/{entity_id})
	GetEntity(ctx context.Context, request GetEntityRequestObject) (GetEntityResponseObject, error)
	// PatchEntity Report changed components of the authenticated Asset
	// (PATCH /entities/{entity_id})
	PatchEntity(ctx context.Context, request PatchEntityRequestObject) (PatchEntityResponseObject, error)
	// CheckInAsset Check in, reporting current Asset state and contact
	// (POST /entities/{entity_id}/checkin)
	CheckInAsset(ctx context.Context, request CheckInAssetRequestObject) (CheckInAssetResponseObject, error)
	// GetAssetStatus Read an Asset's status and contact freshness
	// (GET /entities/{entity_id}/status)
	GetAssetStatus(ctx context.Context, request GetAssetStatusRequestObject) (GetAssetStatusResponseObject, error)
	// ReportAssetStatus Report an Asset's own operational status
	// (PATCH /entities/{entity_id}/status)
	ReportAssetStatus(ctx context.Context, request ReportAssetStatusRequestObject) (ReportAssetStatusResponseObject, error)
	// GetHealth Check process liveness
	// (GET /health)
	GetHealth(ctx context.Context, request GetHealthRequestObject) (GetHealthResponseObject, error)
	// ListPlugins Discover installed Plugins and their availability
	// (GET /plugins)
	ListPlugins(ctx context.Context, request ListPluginsRequestObject) (ListPluginsResponseObject, error)
	// GetPlugin Inspect one installed Plugin
	// (GET /plugins/{plugin_id})
	GetPlugin(ctx context.Context, request GetPluginRequestObject) (GetPluginResponseObject, error)
	// ListPluginOperations List a Plugin's retained Operation attempts, newest first
	// (GET /plugins/{plugin_id}/operations)
	ListPluginOperations(ctx context.Context, request ListPluginOperationsRequestObject) (ListPluginOperationsResponseObject, error)
	// SubmitPluginOperation Submit a durable Operation attempt
	// (POST /plugins/{plugin_id}/operations)
	SubmitPluginOperation(ctx context.Context, request SubmitPluginOperationRequestObject) (SubmitPluginOperationResponseObject, error)
	// GetPluginOperation Read a retained Operation attempt and its known outcome
	// (GET /plugins/{plugin_id}/operations/{operation_id})
	GetPluginOperation(ctx context.Context, request GetPluginOperationRequestObject) (GetPluginOperationResponseObject, error)
	// CancelPluginOperation Request cancellation of one Operation attempt
	// (POST /plugins/{plugin_id}/operations/{operation_id}/cancel)
	CancelPluginOperation(ctx context.Context, request CancelPluginOperationRequestObject) (CancelPluginOperationResponseObject, error)
	// ReportPluginOperation Report progress or an outcome for one of the Plugin's own attempts
	// (POST /plugins/{plugin_id}/operations/{operation_id}/reports)
	ReportPluginOperation(ctx context.Context, request ReportPluginOperationRequestObject) (ReportPluginOperationResponseObject, error)
	// QueryChangedSince Replay committed changes after a Dataset-bound cursor
	// (GET /queries/changed-since)
	QueryChangedSince(ctx context.Context, request QueryChangedSinceRequestObject) (QueryChangedSinceResponseObject, error)
	// QueryFull Load a paginated operational picture with one baseline
	// (GET /queries/full)
	QueryFull(ctx context.Context, request QueryFullRequestObject) (QueryFullResponseObject, error)
	// GetReadiness Check required storage dependencies
	// (GET /readiness)
	GetReadiness(ctx context.Context, request GetReadinessRequestObject) (GetReadinessResponseObject, error)
}

type StrictHandlerFunc func(ctx context.Context, w http.ResponseWriter, r *http.Request, request any) (any, error)
type StrictMiddlewareFunc func(f StrictHandlerFunc, operationID string) StrictHandlerFunc

type StrictHTTPServerOptions struct {
	RequestErrorHandlerFunc  func(w http.ResponseWriter, r *http.Request, err error)
	ResponseErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

func NewStrictHandler(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: StrictHTTPServerOptions{
		RequestErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		},
		ResponseErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		},
	}}
}

func NewStrictHandlerWithOptions(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc, options StrictHTTPServerOptions) ServerInterface {
	if options.RequestErrorHandlerFunc == nil {
		options.RequestErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	if options.ResponseErrorHandlerFunc == nil {
		options.ResponseErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		}
	}
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: options}
}

type strictHandler struct {
	ssi         StrictServerInterface
	middlewares []StrictMiddlewareFunc
	options     StrictHTTPServerOptions
}

